contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 warpTime, uint256 rollNum) public {
        // Admissible domain: value not equal to 10 ether (the reference only accepts 10).
        vm.assume(value != 10 ether);
        // Keep warpTime in a reasonable range so block.timestamp > pastBlockTime can be satisfied.
        vm.assume(warpTime > 0 && warpTime <= type(uint64).max);
        // Give the caller enough ETH to send `value`.
        vm.deal(address(this), value);
        // Set block timestamp ahead so the timestamp require passes if the call proceeds.
        vm.warp(warpTime);
        // Set block number arbitrarily so the %15 check doesn't interfere with the state change we care about.
        vm.roll(rollNum);
        // Record current pastBlockTime before the call.
        uint256 beforeTime = c.pastBlockTime();
        // Try to call fallback with the given value.
        try c.fallback{value: value}() { } catch { }
        // After the attempt, pastBlockTime must be unchanged because the call should revert (value != 10 ether).
        uint256 afterTime = c.pastBlockTime();
        assertEq(afterTime, beforeTime);
    }
}

