pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blocksToAdvance) public {
        // Restrict to the admissible domain: msg.value != 10 ether (the condition the reference enforces).
        // We also ensure value is less than 2^96 to safely cast to uint96 for address balance comparisons.
        vm.assume(value != 10 ether);
        vm.assume(value <= type(uint96).max);
        // Advance the block timestamp to satisfy the second require in the fallback.
        // We also advance the block number to avoid the transfer condition (mod 15 == 0) which would complicate balance tracking.
        vm.warp(block.timestamp + 1 + blocksToAdvance % 100); // modest warp
        vm.roll(block.number + 1 + (blocksToAdvance % 14)); // ensure block.number % 15 != 0

        // Record state before the call.
        uint256 oldTime = c.pastBlockTime();

        // Deal and prank a caller with the fuzzed value.
        address caller = address(0x1234);
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.fallback{value: value}() { ok = true; } catch { ok = false; }

        // The general rule: if msg.value != 10 ether, the call must revert AND pastBlockTime must stay unchanged.
        // The buggy version allows the call to succeed, and pastBlockTime will be updated.
        assertTrue(!ok && c.pastBlockTime() == oldTime);
    }
}

