pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstBlock, uint256 secondBlock, uint256 callerSeed) public {
        vm.assume(firstBlock >= 1);
        vm.assume(secondBlock >= 1);
        vm.assume(firstBlock <= 1000000);
        vm.assume(secondBlock <= 1000000);
        address actor = address(uint160(uint256(keccak256(abi.encode(callerSeed)))));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // fund the actor
        vm.deal(actor, 30 ether);

        // First call at firstBlock
        vm.roll(firstBlock);
        vm.warp(firstBlock); // pastBlockTime initialized to 0, any positive warp is fine
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Second call at secondBlock, possibly same as firstBlock to test back-to-back
        vm.roll(secondBlock);
        vm.warp(secondBlock);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // If firstBlock != secondBlock and both blocks are in different timestamp contexts,
        // pastBlockTime must reflect the second block's timestamp (the later one).
        // In the reference, if secondBlock < firstBlock, the second call reverts; in the bug, it succeeds and overwrites.
        // The property: if the second call did NOT revert, then pastBlockTime must equal the maximum of the two timestamps used.
        // But we need a pure public-surface check. Instead, assert that if both calls succeeded and actor received transfers,
        // we can detect the overwrite by checking pastBlockTime monotonicity: pastBlockTime must be strictly > the previous timestamp.
        // Since we don't store previous timestamp, we use a different approach:
        // The reference only allows the second call if block.timestamp > pastBlockTime. Therefore, if pastBlockTime equals firstBlock
        // and firstBlock == secondBlock, the second call must have reverted in reference but succeeded in bug.
        // We enforce: if secondBlock == firstBlock (same timestamp), the second call must revert in reference.
        // To capture this universally, we assert: (firstBlock == secondBlock) => second call reverted.
        // However, we don't have a try/catch variable here. We'll restructure with try/catch.
    }
}

