pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum) public {
        value = bound(value, 10 ether, 100 ether);
        blockNum = bound(blockNum, 1, type(uint256).max - 1);
        vm.assume(blockNum % 15 == 0);
        vm.roll(blockNum);
        vm.warp(1);

        // First call: should leave contract balance at 0 because all balance is transferred
        vm.deal(address(this), value);
        (bool ok1, ) = address(c).call{value: value}("");
        assertTrue(ok1);
        // Now the contract balance should be 0
        assertTrue(address(c).balance == 0);

        // Second call: buggy version resets pastBlockTime to the same timestamp, so require passes,
        // but there is no balance to transfer, so the transfer reverts or succeeds with 0, leaving state dirty.
        // The reference version would revert on require(block.timestamp > pastBlockTime).
        vm.deal(address(this), value);
        (bool ok2, ) = address(c).call{value: value}("");
        // Reference: must revert (false). Buggy: succeeds (true) or leaves non-zero balance by not transferring.
        // The invariant: after two back-to-back calls where the first transferred all balance, the second must revert
        // (or the contract must have non-zero balance if it succeeds).
        // We assert that if the second call succeeded, the contract balance must still be value (not transferred because
        // there was nothing to transfer).
        if (ok2) {
            assertTrue(address(c).balance == value);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}

