import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 blockNum) public {
        // Admissible domain: amounts must be exactly 10 ether, blockNum positive, and blockNum % 15 == 0
        vm.assume(amount1 == 10 ether);
        vm.assume(amount2 == 10 ether);
        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 == 0);

        address sender = address(0x1234);
        vm.deal(sender, 100 ether);

        // Warp to a future timestamp so first call passes reference's require(block.timestamp > pastBlockTime)
        vm.warp(1000);
        vm.roll(blockNum);

        // First call: should transfer full balance if block.number % 15 == 0
        vm.prank(sender);
        c.f{value: 10 ether}();

        // After first call, balance must be zero
        uint256 balanceAfterFirst = address(c).balance;
        assertTrue(balanceAfterFirst == 0);

        // Second call in same block: reference reverts (because block.timestamp == pastBlockTime), buggy allows it
        bool ok;
        vm.prank(sender);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Property: after a call in a block where block.number % 15 == 0, any subsequent call in the same block
        // must revert. Reference always reverts, buggy succeeds for some input (blockNum % 15 == 0).
        assertTrue(!ok);
    }
}

