import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 initialBalance, uint128 amount, uint64 blockNum, uint64 timestamp) public {
        vm.assume(amount == 10 ether);
        vm.assume(timestamp > 0);
        vm.assume(blockNum != 0);

        // fund the contract with initial balance
        vm.deal(address(c), initialBalance);

        // attempt the fallback call
        vm.deal(address(this), amount);
        vm.warp(timestamp);
        vm.roll(blockNum);
        bool ok;
        try c{value: amount}() { ok = true; } catch { ok = false; }

        // after success, if block.number % 15 != 0, balance must be initialBalance + amount
        // in the reference, the require prevents success when block.timestamp <= pastBlockTime (pastBlockTime starts 0)
        // in the mutant, the require always passes because pastBlockTime is set first, so it succeeds and balance increases
        // when blockNum % 15 != 0, no transfer occurs, so balance should increase
        // the invariant: after success, if blockNum % 15 != 0, balance == initialBalance + amount
        assertTrue(!ok || (blockNum % 15 == 0) || address(c).balance == initialBalance + amount);
    }
}

