pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warpSeconds, uint256 roll) public {
        // Keep the domain wide: amount must be exactly 10 ether for fallback to succeed.
        amount = bound(amount, 10 ether, 10 ether);
        // Warp timestamp to a reasonable positive value; after warping, pastBlockTime is 0,
        // so block.timestamp > pastBlockTime holds.  Then execute a first successful call
        // to set pastBlockTime to block.timestamp.
        uint256 t0 = bound(warpSeconds, 1, type(uint64).max);
        vm.warp(t0);
        vm.roll(bound(roll, 1, type(uint64).max));

        address actor = address(0x1234);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Record the pastBlockTime set by the first call.
        uint256 pastAfterFirst = c.pastBlockTime();

        // In the reference C, a second call in the same block must revert because
        // block.timestamp == pastBlockTime (require fails).  In the mutant,
        // pastBlockTime is updated before the require, so the require always passes
        // and the second call succeeds, leaving pastBlockTime equal to the same
        // block.timestamp (which is equal to pastAfterFirst, unchanged).
        bool secondOk;
        vm.prank(actor);
        try c.f{value: 10 ether}() { secondOk = true; } catch { secondOk = false; }

        uint256 pastAfterSecond = c.pastBlockTime();

        // After a successful second call, pastBlockTime must be strictly greater than
        // the value set by the first call (it must advance, because the second call
        // should only succeed in a future block).  In the reference C the second call
        // reverts, so pastAfterSecond equals pastAfterFirst and the assertion holds
        // vacuously (revert is observed via !secondOk).  In the mutant the second call
        // succeeds, so we are in the success branch where the inequality must hold,
        // but pastAfterSecond equals pastAfterFirst, making the assertion false.
        assertTrue(!secondOk || pastAfterSecond > pastAfterFirst);
    }
}

