pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 blockNumber, uint256 timestamp, uint256 senderSeed) public {
        // Bound blockNumber to a range where divisible by 15 is possible.
        blockNumber = bound(blockNumber, 1, type(uint256).max - 15);
        // Bound timestamp to avoid overflow and satisfy > pastBlockTime.
        timestamp = bound(timestamp, 1, type(uint256).max - 1);
        // Derive a unique sender address from the seed.
        address sender = address(uint160(uint256(keccak256(abi.encode(senderSeed)))));
        vm.assume(sender != address(0));

        // Set up EVM state.
        vm.roll(blockNumber);
        vm.warp(timestamp);

        // Ensure sender has enough ether to send 10 ether.
        vm.deal(sender, 20 ether);

        // Record balance before the call.
        uint256 balanceBefore = address(c).balance;

        // Invoke the fallback function.
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted");

        // After the call, check the invariant.
        // If the transfer condition (block.number % 15 == 0) was met,
        // the contract balance MUST be zero (all ether transferred).
        // If not met, no such invariant applies; we only assert when transfer happens.
        if (blockNumber % 15 == 0) {
            assertEq(address(c).balance, 0 ether, "Contract balance must be 0 after transfer");
        }
    }
}
